def predict(df, p):
    def solve_one(dose, ts):
        ts = np.asarray(ts, float)
        def f(t, y):
            C = pk_conc(dose, t)
            R = y[0]
            return [p['kout']*p['R0']*(1 - p['Imax']*C/(p['IC50']+C)) - p['kout']*R]
        # model II: kout inhibited
        def g(t, y):
            C = pk_conc(dose, t)
            R = y[0]
            return [p['kout']*p['R0'] - p['kout']*R*(1 + p['Imax']*C/(p['IC50']+C))]
        sol = solve_ivp(g, (0, max(ts)+1e-9), [p['R0']], t_eval=ts, rtol=1e-8, atol=1e-8)
        return sol.y[0]
    return per_dose(df, solve_one)

